272	func TestGraphModeCompensatesInReverseConfirmationOrder(t *testing.T) {
273		// 声明顺序 [slow fast failer]，确认顺序为 fast、slow（fast 先完成），
274		// 补偿应按确认逆序：先 slow 后 fast——与声明逆序不同，可区分两种口径。
275		store := NewMemoryStore()
276		eng := NewEngine(store)
277		rec := &dagRecorder{}
278		gateSlow := newGate()
279	
280		mk := func(name string, deps ...string) Step {
281			return Step{
282				Name:      name,
283				DependsOn: deps,
284				Action: func(ctx context.Context, _ ExecutionView) error {
285					if name == "slow" {
286						if err := gateSlow.wait(ctx); err != nil {
287							return err
288						}
289					}
290					rec.log("done:" + name)
291					return nil
292				},
293				Compensate: func(context.Context, ExecutionView) error {
294					rec.log("undo:" + name)
295					return nil
296				},
297			}
298		}
299		failer := Step{
300			Name:      "failer",
301			DependsOn: []string{"slow", "fast"},
302			Action: func(context.Context, ExecutionView) error {
303				rec.log("done:failer")
304				return errors.New("boom-failer")
305			},
306			Compensate: func(context.Context, ExecutionView) error {
307				rec.log("undo:failer")
308				return nil
309			},
310		}
311		def := Definition{
312			Name: "dag-saga", Version: "v1",
313			Steps: []Step{mk("slow"), mk("fast"), failer},
314		}
315	
316		done := make(chan Result, 1)
317		go func() {
318			res, _ := eng.Execute(context.Background(), def, ExecutionRequest{
319				BusinessKey: "biz-dag-3", IdempotencyKey: "req-dag-3",
320			})
321			done <- res
322		}()
323		// 等 fast 确认后再放行 slow，确保确认顺序为 fast -> slow。
324		deadline := time.After(2 * time.Second)
325		for indexOf(rec.snapshot(), "done:fast") < 0 {
326			select {
327			case <-deadline:
328				t.Fatal("fast never done")
329			default:
330				time.Sleep(time.Millisecond)
331			}
332		}
333		gateSlow.open()
334		res := <-done
335	
336		if res.Status != StatusFailed || !res.Terminal {
337			t.Fatalf("status=%s want failed", res.Status)
338		}
339		if res.FailedStep != "failer" || res.FailureReason != "boom-failer" {
340			t.Fatalf("failure info: %+v", res)
341		}
342		got := rec.snapshot()
343		// 确认顺序：fast 先于 slow。
344		if indexOf(got, "done:fast") > indexOf(got, "done:slow") {
345			t.Fatalf("confirmation order unexpected: %v", got)
346		}
347		// 补偿顺序为确认逆序：slow 先补偿，fast 后补偿（声明逆序则相反）。
348		if indexOf(got, "undo:slow") < 0 || indexOf(got, "undo:fast") < 0 ||
349			indexOf(got, "undo:slow") > indexOf(got, "undo:fast") {
350			t.Fatalf("compensation not in reverse confirmation order: %v", got)
351		}
352		// 失败步骤未确认成功，不补偿。
353		if indexOf(got, "undo:failer") >= 0 {
354			t.Fatalf("failed step compensated: %v", got)
355		}
356		results := map[string]string{}
357		for _, so := range res.Steps {
358			results[so.Name] = so.Result
359		}
360		if results["slow"] != StepResultCompensated || results["fast"] != StepResultCompensated ||
361			results["failer"] != StepResultFailed {
362			t.Fatalf("step results = %v", results)
363		}
364	}
