468	func TestGraphModeSameIdentityRetryAfterCancel(t *testing.T) {
469		// a 快速确认，b 阻塞至 ctx 取消：取消后 a 已提交、b 未确认；
470		// 同身份再次调用只重入 b（及其下游 c），a 不得重复调用。
471		store := NewMemoryStore()
472		eng := NewEngine(store)
473		rec := &dagRecorder{}
474		gateB := newGate()
475		var aCalls, bCalls int32
476		var mu sync.Mutex
477		count := func(name string) {
478			mu.Lock()
479			defer mu.Unlock()
480			if name == "a" {
481				aCalls++
482			} else {
483				bCalls++
484			}
485		}
486	
487		def := Definition{
488			Name: "dag-saga", Version: "v1",
489			Steps: []Step{
490				{Name: "a", Action: func(context.Context, ExecutionView) error {
491					count("a")
492					rec.log("done:a")
493					return nil
494				}},
495				{Name: "b", Action: func(ctx context.Context, _ ExecutionView) error {
496					count("b")
497					return gateB.wait(ctx)
498				}},
499				{Name: "c", DependsOn: []string{"b"}, Action: func(context.Context, ExecutionView) error {
500					rec.log("done:c")
501					return nil
502				}},
503			},
504		}
505		req := ExecutionRequest{BusinessKey: "biz-dag-5", IdempotencyKey: "req-dag-5"}
506	
507		ctx, cancel := context.WithCancel(context.Background())
508		done := make(chan error, 1)
509		go func() {
510			_, err := eng.Execute(ctx, def, req)
511			done <- err
512		}()
513		// 等 a 确认提交后取消 ctx：b 的动作随 ctx 结束，不被确认。
514		deadline := time.After(2 * time.Second)
515		for indexOf(rec.snapshot(), "done:a") < 0 {
516			select {
517			case <-deadline:
518				t.Fatal("a never done")
519			default:
520				time.Sleep(time.Millisecond)
521			}
522		}
523		time.Sleep(20 * time.Millisecond) // 让 a 的成功提交落库
524		cancel()
525		if err := <-done; !errors.Is(err, context.Canceled) {
526			t.Fatalf("Execute = %v, want context.Canceled", err)
527		}
528	
529		snap, err := store.LoadSnapshot(context.Background(), "biz-dag-5", "req-dag-5")
530		if err != nil {
531			t.Fatal(err)
532		}
533		if snap.State.Steps[0].Status != StepResultSucceeded || snap.State.Steps[1].Status != "" {
534			t.Fatalf("state after cancel: %+v", snap.State.Steps)
535		}
536	
537		// 同身份、新 context 继续：只重入未确认的 b 与下游 c。
538		gateB.open()
539		res, err := eng.Execute(context.Background(), def, req)
540		if err != nil {
541			t.Fatalf("retry Execute: %v", err)
542		}
543		if res.Status != StatusCompleted {
544			t.Fatalf("status=%s want completed", res.Status)
545		}
546		mu.Lock()
547		defer mu.Unlock()
548		if aCalls != 1 {
549			t.Fatalf("confirmed step re-invoked: a calls=%d", aCalls)
550		}
551		if bCalls != 2 {
552			t.Fatalf("unconfirmed step not re-entered exactly once more: b calls=%d", bCalls)
553		}
554	}
