			Action: func(ctx context.Context, _ ExecutionView) error {
				rec.log("start:" + name)
				if err := g.wait(ctx); err != nil {
					return err
				}
				rec.log("done:" + name)
				return nil
			},
		}
	}
	gateC := newGate()
	gateC.open()
	def := Definition{
		Name: "dag-capped-wide", Version: "v1", MaxConcurrency: 10,
		Steps: []Step{
			gated("a", gateA),
			gated("b", gateB),
