		},
	}

	done := make(chan error, 1)
	go func() {
		_, err := eng.Execute(context.Background(), def, ExecutionRequest{
			BusinessKey: "biz-cap-6", IdempotencyKey: "req-cap-6",
		})
		done <- err
	}()
	// 两个根步骤都应在任一放行前启动（上限未构成约束）。
	waitForEntry(t, rec, "start:a")
